// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ChatGroup) predicate.ChatGroup {
	return predicate.ChatGroup(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ChatGroup) predicate.ChatGroup {
	return predicate.ChatGroup(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ChatGroup) predicate.ChatGroup {
	return predicate.ChatGroup(sql.NotPredicates(p))
}
